{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"CA","category":"security_deposits","lifecycle":"enacted","title":"California security deposit cap and return rules (AB 12)","requirement":"A landlord may not charge more than one month's rent as a security deposit, except small landlords of at most two properties with four units total may charge two months. Deposits must be returned within 21 days with an itemized statement and proof of repairs.","key_value":"1 month's rent (2 months for small landlords)","coverage_conditions":"All residential rental tenancies in California. Small-landlord exception covers owners of only two rental properties with no more than four residential units total.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Small-landlord exception: two rental properties, four residential units total"},"exemptions":"Landlords owning only two rental properties with no more than four residential units total, where ownership is held by a natural person, family trust, or LLC whose members are all natural persons, may charge up to two months' rent.","penalty":null,"effective_date":"2024-07-01","citation":"AB 12","quoted_span":"Starting July 1, 2024, many landlords may only charge one month's rent for unfurnished and furnished units","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest","requirement":"Landlords of units fully or partially covered by the Berkeley Rent Ordinance must pay tenants interest on their security deposit at the end of each year, plus a prorated amount if the tenant moves out earlier.","key_value":null,"coverage_conditions":"Tenancies in units fully or partially covered by Berkeley's Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Units fully or partially covered by the Berkeley Rent Ordinance"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Rent Ordinance","quoted_span":"For tenancies in units fully or partially covered by Berkeley's Rent Ordinance, landlords must pay tenants interest on their security deposit at the end of each year and a prorated amount if the tenant moves out before the end of the year.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
